// 智能选择素材和产品
const materials = $('查询素材库').first().json.results || [];
const products = $('查询产品库').first().json.results || [];

if (materials.length === 0) {
  throw new Error('素材库为空，请先添加素材');
}
if (products.length === 0) {
  throw new Error('产品库为空，请先添加产品');
}

// 随机选择1条素材
const material = materials[Math.floor(Math.random() * materials.length)];
const materialProps = material.properties;

// 根据素材的MBTI标签匹配产品
const materialMBTI = materialProps['MBTI相关']?.multi_select?.map(t => t.name) || [];
let matchedProducts = products.filter(p => {
  const productMBTI = p.properties['适配MBTI']?.multi_select?.map(t => t.name) || [];
  return materialMBTI.some(m => productMBTI.includes(m));
});

// 如果没有匹配的，随机选择
if (matchedProducts.length === 0) {
  matchedProducts = products;
}

// 选择1-2款产品
const selectedProducts = matchedProducts
  .sort(() => Math.random() - 0.5)
  .slice(0, Math.random() > 0.5 ? 2 : 1);

// 获取平台列表
const platforms = (process.env.CONTENT_PLATFORMS || '小红书,微信公众号').split(',');

// 为每个平台创建任务
const tasks = platforms.map(platform => ({
  json: {
    platform: platform.trim(),
    material: {
      id: material.id,
      title: materialProps['标题']?.title?.[0]?.text?.content || '',
      summary: materialProps['原文摘要']?.rich_text?.[0]?.text?.content || '',
      content: materialProps['详细内容']?.rich_text?.[0]?.text?.content || '',
      keywords: materialProps['话题分类']?.multi_select?.map(t => t.name) || [],
      mbtiTags: materialMBTI
    },
    products: selectedProducts.map(p => ({
      id: p.id,
      name: p.properties['产品名称']?.title?.[0]?.text?.content || '',
      tags: p.properties['产品标签']?.multi_select?.map(t => t.name) || [],
      sellingPoints: p.properties['核心卖点']?.rich_text?.[0]?.text?.content || '',
      scenarios: p.properties['使用场景']?.rich_text?.[0]?.text?.content || '',
      mbti: p.properties['适配MBTI']?.multi_select?.map(t => t.name) || []
    }))
  }
}));

return tasks;

// 生成标题Prompt
const d = $json;
const platform = d.platform;
const material = d.material;
const products = d.products;

const titleLength = platform === '小红书' ? '15-25字' : '10-30字';
const titleStyle = platform === '小红书' ? '口语化、有emoji' : '专业、有深度';

const prompt = `你是${platform}内容创作专家。

任务：为以下素材生成吸引眼球的标题。

素材信息：
- 标题：${material.title}
- 摘要：${material.summary}
- 关键词：${material.keywords.join('、')}

产品信息：
${products.map(p => `- ${p.name}：${p.sellingPoints}`).join('\n')}

要求：
1. 字数：${titleLength}
2. 风格：${titleStyle}
3. 包含价值点（知识/情感/实用）
4. 自然植入产品（不要硬广）
5. 避免标题党和夸张

直接返回标题文本，不要解释。`;

return [{ json: { ...d, titlePrompt: prompt } }];

// 提取标题
const d = $('生成标题Prompt').item.json;
const aiResponse = $json;

let title = d.material.title; // 默认使用素材标题
try {
  title = aiResponse.content?.[0]?.text?.trim() || title;
} catch (e) {}

return [{ json: { ...d, generatedTitle: title } }];

// 生成正文Prompt
const d = $json;
const platform = d.platform;
const material = d.material;
const products = d.products;

const wordCount = platform === '小红书' ? '800-1200字' : '2000-3000字';
const structure = platform === '小红书' 
  ? '开头（引入话题）→ 知识科普 → 产品植入 → 互动引导'
  : '引言 → 深度分析 → 实践建议 → 产品推荐 → 总结';

const prompt = `你是${platform}内容创作专家。

任务：创作一篇营销内容。

标题：${d.generatedTitle}

素材信息：
- 核心内容：${material.content}
- 关键词：${material.keywords.join('、')}
- MBTI标签：${material.mbtiTags.join('、')}

产品信息：
${products.map(p => `
产品：${p.name}
卖点：${p.sellingPoints}
场景：${p.scenarios}
MBTI：${p.mbti.join('、')}
`).join('\n')}

品牌理念：不被定义，自己定义

要求：
1. 字数：${wordCount}
2. 结构：${structure}
3. 内容比例：70%教育价值 + 30%产品植入
4. 产品植入方式：场景化、自然、不硬广
5. 语言风格：${platform === '小红书' ? '轻松、口语化、有共鸣' : '专业、深度、有洞察'}
6. 禁忌词：避免绝对化、夸张、标题党

直接返回正文内容（Markdown格式），不要解释。`;

return [{ json: { ...d, contentPrompt: prompt } }];

// 提取正文
const d = $('生成正文Prompt').item.json;
const aiResponse = $json;

let content = d.material.content; // 默认使用素材内容
try {
  content = aiResponse.content?.[0]?.text?.trim() || content;
} catch (e) {}

return [{ json: { ...d, generatedContent: content } }];

// 生成配图Prompt
const d = $json;
const platform = d.platform;
const imageCount = platform === '小红书' ? 9 : 3;

const prompt = `基于以下内容，生成${imageCount}张配图的描述：

标题：${d.generatedTitle}

内容摘要：${d.material.summary}

产品：${d.products.map(p => p.name).join('、')}

要求：
1. 每张图片用一句话描述（中文）
2. 风格：${platform === '小红书' ? '清新、时尚、年轻化' : '专业、简洁、有质感'}
3. 包含：产品图、场景图、氛围图
4. 适合${platform}平台

返回JSON数组格式：
["图片1描述", "图片2描述", ...]`;

return [{ json: { ...d, imagePrompt: prompt, imageCount } }];

// 解析配图描述
const d = $('生成配图Prompt').item.json;
const aiResponse = $json;

let imageDescriptions = [];
try {
  const content = aiResponse.content?.[0]?.text?.trim() || '[]';
  imageDescriptions = JSON.parse(content);
} catch (e) {
  // 解析失败，生成默认描述
  for (let i = 0; i < d.imageCount; i++) {
    imageDescriptions.push(`${d.products[0]?.name || '产品'}配图${i+1}`);
  }
}

return [{ json: { ...d, imageDescriptions } }];

// 使用Nano Banana生成图片
const d = $json;
const descriptions = d.imageDescriptions;

// 为每个描述创建生成任务
const tasks = descriptions.map((desc, index) => ({
  json: {
    ...d,
    currentImageIndex: index,
    currentImageDesc: desc,
    imagePrompt: `${desc}, high quality, professional photography, clean background`
  }
}));

return tasks;

// 提取图片URL
const d = $('准备图片生成').item.json;
const response = $json;

let imageUrl = '';
try {
  imageUrl = response.data?.[0]?.url || '';
} catch (e) {}

return [{
  json: {
    index: d.currentImageIndex,
    description: d.currentImageDesc,
    url: imageUrl
  }
}];

// 整合所有内容
const d = $('解析配图描述').item.json;
const images = $input.first().json.data || [];

// 生成话题标签
const tags = [
  ...d.material.keywords,
  ...d.products.flatMap(p => p.tags),
  ...d.material.mbtiTags
].filter((v, i, a) => a.indexOf(v) === i).slice(0, 10);

return [{
  json: {
    contentId: `CONTENT-${Date.now()}`,
    title: d.generatedTitle,
    platform: d.platform,
    content: d.generatedContent,
    tags: tags,
    images: images,
    materialId: d.material.id,
    productIds: d.products.map(p => p.id),
    generationMethod: 'AI生成',
    aiModel: process.env.AI_MODEL || 'claude-3-5-sonnet-20241022',
    contentStrategy: '教育式',
    wordCount: d.generatedContent.length,
    status: '待审核',
    createdAt: new Date().toISOString()
  }
}];

// 构建Notion请求
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_CONTENT_DB_ID },
  properties: {
    '内容ID': { rich_text: [{ text: { content: d.contentId } }] },
    '标题': { title: [{ text: { content: d.title.substring(0, 100) } }] },
    '平台': { select: { name: d.platform } },
    '完整正文': { rich_text: [{ text: { content: d.content.substring(0, 2000) } }] },
    '话题标签': { multi_select: d.tags.map(t => ({ name: t })) },
    '配图建议': { rich_text: [{ text: { content: JSON.stringify(d.images, null, 2).substring(0, 2000) } }] },
    '关联素材ID': { rich_text: [{ text: { content: d.materialId } }] },
    '关联产品ID': { rich_text: [{ text: { content: d.productIds.join(',') } }] },
    '生成方式': { select: { name: d.generationMethod } },
    'AI模型': { rich_text: [{ text: { content: d.aiModel } }] },
    '内容策略': { select: { name: d.contentStrategy } },
    '字数统计': { number: d.wordCount },
    '状态': { select: { name: d.status } }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 生成执行摘要
const items = $input.first().json.data || [];
const successCount = items.filter(item => item.id).length;

const summary = `内容创作报告
==================
执行时间: ${new Date().toLocaleString('zh-CN')}

【创作结果】
- 成功: ${successCount}篇
- 失败: ${items.length - successCount}篇

【平台分布】
${items.map(item => {
  const d = item.originalData;
  return `- ${d?.platform}: 《${d?.title}》`;
}).join('\n')}

【生成内容】
${items.map((item, i) => {
  const d = item.originalData;
  return `${i+1}. [${d?.platform}] ${d?.title}\n   字数:${d?.wordCount} 配图:${d?.images?.length || 0}张 状态:${d?.status}`;
}).join('\n\n')}

【下一步】
1. 在Notion内容库中审核内容
2. 修改优化后标记为

3. 使用发布工作流发布内容`;

return [{
  json: {
    report: summary,
    successCount,
    totalCount: items.length,
    timestamp: new Date().toISOString()
  }
}];
